{
  "omongan": [
    {
      "no": 1,
      "nama": "Dewi",
      "jam": "18.30",
      "pesan": "Gue baca saham ini kena suspensi 30 Juni gara-gara laporan keuangan auditan belum masuk. Sampai sekarang, 8 Oktober, berarti belum bisa diperdagangkan dong?",
      "angka_pesan": [
        {"teks": "30 Juni", "fact_id": "susp-2025-06-30"},
        {"teks": "8 Oktober", "fact_id": "harga-2025-10-08"}
      ],
      "kartu": ["susp-2025-06-30", "harga-2025-10-08", "volume-2025-10-08"],
      "kartu_penentu": ["harga-2025-10-08", "volume-2025-10-08"],
      "pilihan": {
        "a": "Betul, penghentian [[susp-2025-06-30|30 Juni 2025]] belum dicabut sampai sekarang.",
        "b": "Keliru, [[harga-2025-10-08|8 Oktober 2025]] sudah ada harga penutupan, jadi saham diperdagangkan lagi.",
        "c": "Betul, penyebab penghentiannya memang laporan keuangan auditan yang belum disampaikan.",
        "d": "Keliru, catatan bursa tidak pernah menyebut penghentian di [[susp-2025-06-30|30 Juni 2025]]."
      },
      "kunci": "b",
      "penjelasan": "Penghentian perdagangan memang tercatat mulai [[susp-2025-06-30|30 Juni 2025]] karena laporan keuangan auditan tahunan belum disampaikan. Tapi data harga harian bursa menunjukkan pada [[harga-2025-10-08|8 Oktober 2025]] sudah ada harga penutupan [[harga-2025-10-08|178 rupiah]] per lembar, dan volume perdagangan [[volume-2025-10-08|324.690.400 lembar]]. Artinya saham itu sudah diperdagangkan lagi pada tanggal itu, jadi anggapan bahwa sampai sekarang belum bisa diperdagangkan tidak sesuai dengan catatan. Salah-kaprah yang umum: penghentian sementara dikira masih berlanjut karena tidak ada berita pencabutan, padahal data perdagangan harian sudah menunjukkan sebaliknya."
    }
  ]
}

